def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0.0)))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 18.0))

    max_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    desperation = 0.0
    if hp <= 2:
        desperation += 0.75
    elif hp <= 4:
        desperation += 0.4
    if no_water_days >= 2:
        desperation += 0.7
    elif no_water_days >= 1:
        desperation += 0.25
    if day >= 8:
        desperation += 0.15

    base = 24.0 + 16.0 * scarcity + 10.0 * desperation

    if supply <= 16:
        base += 8.0
    elif supply >= 23:
        base -= 6.0

    if max_prev_bid >= 100.0:
        if hp > 4 and no_water_days == 0:
            base -= 8.0
        else:
            base += 6.0
    elif max_prev_bid >= 80.0:
        if hp > 5 and no_water_days == 0:
            base -= 5.0
        else:
            base += 4.0
    elif max_prev_bid > 0.0:
        target_react = max_prev_bid + 2.0
        if target_react > base:
            base = 0.6 * base + 0.4 * target_react

    if urgent_opp >= 2:
        base += 4.0
    elif urgent_opp == 0 and avg_prev_bid >= 80.0 and hp > 4:
        base -= 4.0

    reserve_target = DAILY_SALARY * max(0, 10 - day)
    if budget < reserve_target * 0.6:
        base -= 5.0
    if budget > reserve_target * 1.2:
        base += 3.0
    if rich_opp >= 2 and hp > 4 and no_water_days == 0:
        base -= 2.0

    if hp <= 2 or no_water_days >= 2:
        floor_bid = 52.0 + 10.0 * scarcity
        if base < floor_bid:
            base = floor_bid

    if day == 1 and hp >= 8:
        base -= 3.0

    bid = max(0.0, min(budget, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Use only yesterday previous_trace for immediate reaction
    prev_bids = []
    prev_pressured = 0
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                b = float(bid)
                prev_bids.append(b)
                if b >= DAILY_SALARY * 0.85:
                    prev_pressured += 1
            except Exception:
                pass

    # Estimate how likely we are to get water without going extreme
    supply_factor = 0.0
    if MAX_SUPPLY > 0:
        supply_factor = (supply - float(WATER_REQ)) / float(MAX_SUPPLY - float(WATER_REQ))
    if supply_factor < 0.0:
        supply_factor = 0.0
    if supply_factor > 1.0:
        supply_factor = 1.0

    # Base bid: if we are at risk (low hp or many no-water days), bid more aggressively.
    risk = 0
    if hp <= 2:
        risk += 2
    elif hp <= 4:
        risk += 1
    if no_water_days >= 2:
        risk += 1

    # Competitive adjustment from yesterday
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        max_prev = 0.0
        avg_prev = 0.0

    # If opponents were pressuring heavily yesterday, we slightly shadow the high end.
    # Otherwise, stay near a moderate level to conserve budget.
    if prev_pressured >= 1 and max_prev > 0:
        target = 0.72 * max_prev
        if risk >= 2:
            target = max(target, 0.85 * max_prev)
    else:
        # Moderate: use average if available, else a safe fraction of daily salary.
        target = avg_prev if avg_prev > 0 else DAILY_SALARY * 0.55
        # If supply is tight, lean upward; if ample, lean downward.
        target = target + (1.0 - supply_factor) * (DAILY_SALARY * 0.15) - supply_factor * (DAILY_SALARY * 0.05)
        if risk >= 2:
            target = max(target, DAILY_SALARY * 0.75)

    # Clamp to reasonable bounds and budget
    # Also ensure we don't bid above what we can afford.
    min_bid = DAILY_SALARY * 0.35
    max_bid = min(budget, DAILY_SALARY * 0.98)

    if budget <= 0:
        return 0.0

    # If we are very likely to need water soon, bump a bit.
    if no_water_days >= 3:
        target = max(target, DAILY_SALARY * 0.9)

    bid = float(target)
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    # If supply is extremely low relative to requirement, bid harder.
    if supply < float(WATER_REQ) + 1.0:
        bid = min(max_bid, max(bid, DAILY_SALARY * 0.85))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
    max_prev_bid = max(yesterday_bids)

    if my_status['hp'] < 4:
        return min(my_status['budget'], max_prev_bid * 1.15)

    bid = min(my_status['budget'], max(avg_prev_bid * 1.05, DAILY_SALARY * 0.5))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    my_current_budget = my_status['budget']
    my_current_hp = my_status['hp']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.1)

    strong_opponent_ids = ["Alex", "Cindy"]
    strong_competitors_alive = []
    for opp_id in strong_opponent_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            strong_competitors_alive.append(opponents_status[opp_id])

    highest_strong_opp_prev_bid = 0.0
    for opp in strong_competitors_alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_strong_opp_prev_bid = max(highest_strong_opp_prev_bid, prev['bid'])

    available_water_slots = int(current_supply // WATER_REQ)

    base_bid = DAILY_SALARY * 0.6

    if my_current_hp <= 2:
        base_bid = DAILY_SALARY * 0.98
    elif my_current_hp <= 4:
        base_bid = DAILY_SALARY * 0.85
    elif my_current_hp >= 8:
        base_bid = DAILY_SALARY * 0.55

    if current_day >= EPISODE_DAYS - 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif current_day >= EPISODE_DAYS - 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.75)

    num_potential_winners = len(strong_competitors_alive) + 1
    if highest_strong_opp_prev_bid > 0:
        if available_water_slots < num_potential_winners:
            base_bid = max(base_bid, highest_strong_opp_prev_bid + 2.0)
        elif available_water_slots == num_potential_winners:
            base_bid = max(base_bid, highest_strong_opp_prev_bid + 1.0)
        else:
            base_bid = max(base_bid, highest_strong_opp_prev_bid * 0.9)

    if my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 0.99

    final_bid = min(my_current_budget, base_bid)
    final_bid = min(final_bid, DAILY_SALARY)

    return max(1.0, final_bid)
